package dev.industrialtechnology.test;
import java.util.*;import java.io.*;import java.nio.file.*;import java.nio.charset.StandardCharsets;
import cpw.mods.fml.common.*;import cpw.mods.fml.common.event.*;import cpw.mods.fml.common.eventhandler.SubscribeEvent;import cpw.mods.fml.common.gameevent.TickEvent;
import dev.industrialtechnology.core.*;import dev.industrialtechnology.console.*;import dev.industrialtechnology.wireless.*;import dev.industrialtechnology.capacitor.*;
import net.minecraft.world.*;import net.minecraft.server.MinecraftServer;import net.minecraft.tileentity.*;import net.minecraft.item.*;import net.minecraft.init.*;import net.minecraft.nbt.*;import net.minecraft.entity.player.*;import net.minecraftforge.common.util.*;
@Mod(modid="industrialtech_console_checks",name="Disposable console checks",version="1",dependencies="required-after:industrialtech")
public final class ConsoleServerChecks {
    private final List<String> report=new ArrayList<String>();private int ticks,failed;private boolean done;private WorldServer w;private FakePlayer p;private UUID network;
    interface Test{void run()throws Exception;}
    private static void check(boolean value,String message){if(!value)throw new AssertionError(message);}
    private void test(String name,Test code){try{code.run();report.add("PASS: "+name);}catch(Throwable t){failed++;report.add("FAIL: "+name+" :: "+t);IndustrialTechnology.log.error(name,t);}}
    @Mod.EventHandler public void init(FMLInitializationEvent e){if(Boolean.getBoolean("industrialtech.consoleTest"))FMLCommonHandler.instance().bus().register(this);}
    private void prepare(){p=new FakePlayer(w,new com.mojang.authlib.GameProfile(UUID.fromString("2fdc4832-9388-4d47-b635-11811028e000"),"ConsoleTester")){@Override public void sendPlayerAbilities(){}@Override public void addChatMessage(net.minecraft.util.IChatComponent message){}};p.theItemInWorldManager.setGameType(WorldSettings.GameType.SURVIVAL);p.inventory.mainInventory[0]=new ItemStack(ModRegistry.terminal);network=WirelessAccess.terminal(p,p.getHeldItem(),true);}
    private TileConsole place(int x,boolean controller){w.getChunkFromChunkCoords(x>>4,40>>4);w.setBlock(x,70,40,controller?ConsoleRegistry.controller:ConsoleRegistry.history,3,3);TileConsole t=(TileConsole)w.getTileEntity(x,70,40);t.owner=p.getUniqueID();t.network=network;return t;}
    private WirelessEndpoint sensor(int x,WirelessEndpoint.Kind kind){w.getChunkFromChunkCoords(x>>4,50>>4);w.setBlock(x,70,50,WirelessTestFixtures.tanks,0,3);return link(x,70,50,kind);}
    private WirelessEndpoint link(int x,int y,int z,WirelessEndpoint.Kind kind){p.setPosition(x+.5,y,z+2);ItemStack stick=new ItemStack(ItemWirelessStick.item(kind));((ItemWirelessStick)stick.getItem()).onItemUseFirst(stick,p,w,x,y,z,3,.5F,.5F,1);TileRedstoneRelay relay=(TileRedstoneRelay)w.getTileEntity(x,y,z+1);check(relay!=null&&relay.endpoint!=null,"Actual stick did not link");return WirelessData.get(w).devices.get(relay.endpoint);}
    private WirelessEndpoint yellow(int x){w.setBlock(x,70,50,Blocks.iron_block,0,3);return link(x,70,50,WirelessEndpoint.Kind.CONTROL);}
    private WirelessTestFixtures.Tanks tank(WirelessEndpoint e){return (WirelessTestFixtures.Tanks)w.getTileEntity(e.x,e.y,e.z);}
    private ConsoleChannel rule(TileConsole t,WirelessEndpoint b,WirelessEndpoint y){ConsoleChannel c=t.channels[0];c.source=b.id;c.target=y.id;c.low=1000;c.high=3000;c.enabled=true;return c;}
    private void poll(TileConsole t,long tick){t.poll(0,tick);}
    @SubscribeEvent public void tick(TickEvent.ServerTickEvent e){if(done||e.phase!=TickEvent.Phase.END||!MinecraftServer.getServer().isDedicatedServer()||++ticks<80)return;w=MinecraftServer.getServer().worldServerForDimension(0);prepare();if(new File("console-phase1.done").exists()){restart();finish("restart");return;}initial();finish("initial");}
    private void initial(){
        test("Real Green/Blue/Yellow torches link through the existing terminal and history selects linked Greens",()->{TileConsole t=place(10,false);WirelessEndpoint green=sensor(12,WirelessEndpoint.Kind.MONITOR);p.setPosition(10,70,42);check(t.link(p),"bind");check(t.network.equals(network)&&green.id.equals(t.channels[0].source),"auto Green registration");});
        test("Release rule switches actual Yellow redstone ON at High and OFF at Low without chatter",()->{TileConsole t=place(30,true);WirelessEndpoint b=sensor(32,WirelessEndpoint.Kind.AUTOMATION),y=yellow(34);ConsoleChannel c=rule(t,b,y);tank(b).water.setFluid(new net.minecraftforge.fluids.FluidStack(net.minecraftforge.fluids.FluidRegistry.WATER,3000));poll(t,100);check(y.powered&&WirelessAccess.relay(y).signal(),"high did not turn on");tank(b).water.setFluid(new net.minecraftforge.fluids.FluidStack(net.minecraftforge.fluids.FluidRegistry.WATER,2000));poll(t,200);check(y.powered,"middle band chatter");tank(b).water.setFluid(new net.minecraftforge.fluids.FluidStack(net.minecraftforge.fluids.FluidRegistry.WATER,1000));poll(t,300);check(!y.powered,"low did not turn off");});
        test("Refill mode reverses the two limits and manual override still fails closed on bad data",()->{TileConsole t=place(50,true);WirelessEndpoint b=sensor(52,WirelessEndpoint.Kind.AUTOMATION),y=yellow(54);ConsoleChannel c=rule(t,b,y);c.refill=true;poll(t,100);check(y.powered,"refill low");tank(b).water.setFluid(new net.minecraftforge.fluids.FluidStack(net.minecraftforge.fluids.FluidRegistry.WATER,3000));poll(t,200);check(!y.powered,"refill high");c.manual=1;poll(t,300);check(y.powered,"manual on");tank(b).unavailable=true;poll(t,400);check(!y.powered&&c.message.contains("Sensor"),"unavailable should fail closed");});
        test("Changing the fluid type fails closed instead of applying a naphtha rule to another fluid",()->{TileConsole t=place(70,true);WirelessEndpoint b=sensor(72,WirelessEndpoint.Kind.AUTOMATION),y=yellow(74);rule(t,b,y);tank(b).water.setFluid(new net.minecraftforge.fluids.FluidStack(net.minecraftforge.fluids.FluidRegistry.WATER,3000));poll(t,100);check(y.powered,"setup");tank(b).water.setFluid(new net.minecraftforge.fluids.FluidStack(net.minecraftforge.fluids.FluidRegistry.LAVA,3000));poll(t,200);check(!y.powered&&t.channels[0].message.contains("changed"),"wrong fluid controlled output");});
        test("Pausing and breaking a controller turn off only that controller's owned output",()->{TileConsole t=place(90,true);WirelessEndpoint b=sensor(92,WirelessEndpoint.Kind.AUTOMATION),y=yellow(94);rule(t,b,y);tank(b).water.setFluid(new net.minecraftforge.fluids.FluidStack(net.minecraftforge.fluids.FluidRegistry.WATER,3000));poll(t,100);ConsoleContainer c=new ConsoleContainer(t);c.action(13,0,0,0,0,"");check(!y.powered&&!t.channels[0].enabled,"pause all");t.channels[0].enabled=true;poll(t,200);check(y.powered,"resume");w.setBlockToAir(90,70,40);check(!y.powered,"break output remained on");});
        test("A running Blue program and two console rules cannot fight over the same Yellow",()->{TileConsole first=place(110,true),second=place(114,true);WirelessEndpoint b=sensor(112,WirelessEndpoint.Kind.AUTOMATION),y=yellow(116);rule(first,b,y);rule(second,b,y);tank(b).water.setFluid(new net.minecraftforge.fluids.FluidStack(net.minecraftforge.fluids.FluidRegistry.WATER,3000));poll(first,100);poll(second,100);check(y.powered&&second.channels[0].message.contains("another"),"duplicate output claim");ConsoleService.release(first,0,true);b.rules[0].enabled=true;b.rules[0].target=y.id;WirelessAccess.command(WirelessData.get(w),y,"ON",0);poll(first,200);check(y.powered&&first.channels[0].message.contains("Blue"),"controller fought running Blue program");b.rules[0].enabled=false;});
        test("Unavailable history samples are gaps and history survives ordinary NBT round-trip",()->{TileConsole t=place(130,false);WirelessEndpoint g=sensor(132,WirelessEndpoint.Kind.MONITOR);t.channels[0].source=g.id;poll(t,100);tank(g).unavailable=true;poll(t,200);check(t.channels[0].history.value(1)== -1,"offline became zero");NBTTagCompound n=new NBTTagCompound();t.writeToNBT(n);TileConsole copy=new TileConsole.History();copy.readFromNBT(n);check(copy.channels[0].history.size()==2&&copy.channels[0].history.value(0)==1000&&copy.channels[0].history.value(1)== -1,"history NBT");});
        test("Switching fluids starts a new history series while real empty samples remain zero",()->{TileConsole t=place(150,false);WirelessEndpoint g=sensor(152,WirelessEndpoint.Kind.MONITOR);t.channels[0].source=g.id;poll(t,100);tank(g).water.setFluid(null);poll(t,200);check(t.channels[0].history.size()==2&&t.channels[0].history.value(1)==0,"real empty sample missing");tank(g).water.setFluid(new net.minecraftforge.fluids.FluidStack(net.minecraftforge.fluids.FluidRegistry.LAVA,1000));poll(t,300);check(t.channels[0].history.size()==1,"different fluids mixed");});
        test("Console owner, distance and stale-window checks reject forged commands",()->{TileConsole t=place(170,true);p.setPosition(170,70,42);ConsoleContainer c=new ConsoleContainer(t);p.openContainer=c;c.windowId=33;ConsoleCommand.apply(p,new ConsoleCommand(34,10,0,0,1,2,""));check(t.channels[0].high==2000000,"forged window");c.action(10,0,0,2,1,"");check(t.channels[0].high==2000000,"invalid limits");UUID saved=t.owner;t.owner=UUID.randomUUID();ConsoleCommand.apply(p,new ConsoleCommand(33,10,0,0,1,2,""));check(t.channels[0].high==2000000,"foreign owner");t.owner=saved;p.setPosition(0,70,0);ConsoleCommand.apply(p,new ConsoleCommand(33,10,0,0,1,2,""));check(t.channels[0].high==2000000,"remote forged command");});
        test("Source picker cannot select another owner's sensor",()->{TileConsole t=place(190,false);WirelessEndpoint foreign=sensor(192,WirelessEndpoint.Kind.MONITOR);foreign.owner=UUID.randomUUID();ConsoleContainer c=new ConsoleContainer(t);c.action(2,0,0,0,0,"");c.action(5,0,0,0,0,foreign.id.toString());check(t.channels[0].source==null,"foreign sensor accepted");});
        test("Large RF capacitor networks are read as long values without consuming or converting RF",()->{TileCapacitorBank first=null;for(int i=0;i<100;i++){int x=240+i%10,z=80+(i/10);w.setBlock(x,70,z,ModRegistry.capacitorBank,3,3);TileCapacitorBank bank=(TileCapacitorBank)w.getTileEntity(x,70,z);ItemStack stack=new ItemStack(ModRegistry.capacitorBank);NBTTagCompound n=new NBTTagCompound();n.setInteger("BankVersion",1);n.setLong("StoredRF",25000000);stack.setTagCompound(n);bank.restoreItem(stack);if(first==null)first=bank;}WirelessEndpoint green=link(240,70,89,WirelessEndpoint.Kind.MONITOR);SensorReading r=SensorReading.energy(green,0);check(r.available&&r.amount==2500000000L&&r.capacity==2500000000L&&"RF".equals(r.unit),"RF clamped/converted "+r.amount);check(first.snapshot().getLong("Stored")==2500000000L,"read consumed RF");TileConsole t=place(210,false);t.channels[0].source=green.id;poll(t,100);check(t.channels[0].energy&&t.channels[0].history.value(0)==2500000000L,"automatic energy detection");});
        test("Retired solar GUI remains absent and old empty capacitor items still stack",()->{check(IndustrialTechnology.proxy.getServerGuiElement(3,p,w,0,0,0)==null,"solar GUI returned");check(new ItemStack(ModRegistry.capacitorBank).getMaxStackSize()==64,"stacking regression");});
        if(Loader.isModLoaded("hbm"))test("Actual HBM Big-Ass Tank and Yellow-on-battery telemetry use real mB and HE",()->ConsoleHbmChecks.run(w,p,network));
        test("Pickup settings retain links and thresholds, omit large history arrays, and start paused",()->{TileConsole t=place(280,true);t.channels[0].low=100;t.channels[0].high=5555;t.channels[0].enabled=true;t.channels[0].history.add(100,123);NBTTagCompound n=t.itemSettings();ConsoleChannel c=ConsoleChannel.read(n.getTagList("Channels",10).getCompoundTagAt(0));check(!c.enabled&&c.high==5555&&c.history.size()==0,"item settings");});
        test("Selected graph snapshot stays bounded to 720 samples",()->{TileConsole t=place(290,false);for(int i=0;i<900;i++)t.channels[0].history.add(i*100L,i);NBTTagCompound n=new ConsoleContainer(t).snapshot();check(n.getCompoundTag("Row").getIntArray("Times").length==1440,"snapshot unbounded");});
        test("Real world save writes controller band state and history for a genuine JVM restart",()->{TileConsole t=place(304,false);t.channels[0].source=sensor(306,WirelessEndpoint.Kind.MONITOR).id;t.channels[0].expected="water";t.channels[0].seriesKey="mB:water";t.channels[0].history.add(100,123);t.channels[0].history.add(200,456);t.channels[0].high=7654321;TileConsole c=place(312,true);c.channels[0].low=1800000;c.channels[0].high=2000000;c.channels[0].latched=true;w.saveAllChunks(true,null);WirelessData.get(w).markDirty();w.mapStorage.saveAllData();Files.write(Paths.get("console-phase1.done"),Arrays.asList("saved"),StandardCharsets.UTF_8);});
    }
    private void restart(){test("Genuine JVM restart restores network ownership, exact history and controller limits",()->{w.getChunkFromChunkCoords(304>>4,40>>4);TileConsole t=(TileConsole)w.getTileEntity(304,70,40);check(t!=null&&p.getUniqueID().equals(t.owner)&&t.network!=null&&t.channels[0].high==7654321,"console missing");check(t.channels[0].history.size()>=2&&t.channels[0].history.value(0)==123&&t.channels[0].history.value(1)==456,"history lost: size="+t.channels[0].history.size()+", key="+t.channels[0].seriesKey);TileConsole c=(TileConsole)w.getTileEntity(312,70,40);check(c!=null&&c.channels[0].low==1800000&&c.channels[0].high==2000000,"controller limits lost");});}
    private void finish(String phase){if(done)return;done=true;try{report.add("Failed: "+failed);Files.write(Paths.get("console-"+phase+".txt"),report,StandardCharsets.UTF_8);}catch(Exception e){throw new RuntimeException(e);}MinecraftServer.getServer().initiateShutdown();}
}
